def validate_source_path(source_path: str) -> Path:
    path = Path(source_path)

    # 1. 要求绝对路径，否则抛出 InvalidRepositoryInputError
    if not path.is_absolute():
        raise InvalidRepositoryInputError("Source path must be absolute")

    # 2. 解析真实路径，并要求路径存在
    # 将 FileNotFoundError 转换成 InvalidRepositoryInputError
    try:
        resolve_path = path.resolve(strict=True)
    except FileNotFoundError:
        raise InvalidRepositoryInputError("Source path does not exist")

    # 3. 确认解析后的路径是目录
    if not resolve_path.is_dir():
        raise InvalidRepositoryInputError("Source path must be a directory")

    # 4. 返回解析后的 Path
    return resolve_path

def create_workspace(
    workspace_root: Path,
    source_path: Path,
    commit_hash: str,
) -> Path:
    workspace_path = allocate_workspace(
        workspace_root,
        source_path,
    )

    try:
        populate_workspace(
            source_path,
            workspace_path,
            commit_hash,
        )
    except Exception:
        try:
            cleanup_workspace(
                workspace_root,
                workspace_path,
                source_path,
            )
        except Exception:
            # checkout 失败后，删除又因权限失败，记录清理异常，再用最后的裸 raise 重新抛出原来的创建异常
            logger.exception(
                "Workspace cleanup failed; residual directory: %s",
                workspace_path,
            )

        raise

    return workspace_path

@dataclass(frozen=True)
class GitMetadata:
    # 注册时的提交和分支信息；detached HEAD 没有所属分支，git_branch 为 None。
    commit_hash: str
    git_branch: str | None

def discover_python_files(workspace_path: Path) -> list[Path]:
    try:
        # 1. 检查传入的根路径本身是否为链接或重解析点
        # 如果是，抛 RepositoryScanError
        if _is_link_or_reparse_point(workspace_path):
            raise RepositoryScanError()

        root = workspace_path.resolve(strict=True)

        # 2. 确认 root 是目录，否则抛 RepositoryScanError
        if not root.is_dir():
            raise RepositoryScanError()

        files: list[Path] = []

        for current_dir, dirnames, filenames in os.walk(
            root,
            topdown=True,
            followlinks=False,
            onerror=_raise_walk_error,
        ):
            current_path = Path(current_dir)

            # 3. 筛选可以进入的子目录
            # - 名称不在 EXCLUDED_DIRS 中
            # - 不是链接或重解析点
            allowed_dirs = []

            for dirname in dirnames:
                directory_path = current_path / dirname

                if dirname in EXCLUDED_DIRS:
                    continue

                if _is_link_or_reparse_point(directory_path):
                    continue

                allowed_dirs.append(dirname)

            dirnames[:] = allowed_dirs

            for filename in filenames:
                file_path = current_path / filename

                # 4. 跳过链接或重解析点
                # 提示：continue
                if _is_link_or_reparse_point(file_path):
                    continue

                # 5. 只保留扩展名为 .py 的普通文件
                if file_path.suffix == ".py" and file_path.is_file():
                    # 6. 将符合要求的路径加入 files
                    files.append(file_path)

        # 7. 按仓库相对路径排序后返回
        # 提示：sorted(files, key=...)
        # 排序依据：path.relative_to(root).as_posix()
        def relative_path_key(path: Path) -> str:
            return path.relative_to(root).as_posix()

        return sorted(files, key=relative_path_key)

    except OSError as exc:
        raise RepositoryScanError(
            "Cannot scan workspace files"
        ) from exc

@dataclass(frozen=True)
class FileSnapshot:
    # 同一次读取的原始字节和元数据；让 hash/size 与用于分块的内容保持一致。
    # 这是内存快照，不是磁盘备份，也不是一张数据库表。
    metadata: FileMetadata
    content: bytes

@dataclass(frozen=True)
class ChunkedFile:
    # 一个有效文件的元数据和待入库块；空文件/只有常量的文件也有效，chunks 可为空。
    metadata: FileMetadata
    chunks: list[CodeChunkDraft]

@router.get(
    "/{repository_id}/search",
    response_model=list[CodeChunkSearchHit],
)
def search_repository(
    repository_id: UUID,
    query: str = Query(min_length=1, max_length=1000),
    top_k: int = Query(default=5, ge=1, le=20),
):
    # 1. query.strip() 为空时，抛 HTTP 422
    if query.strip() == "":
        raise HTTPException(status_code=422, detail="Query cannot be blank")

    try:
        # 2. 调用 retrieval_service.semantic_search。
        # 传入 repository_id、query、top_k。
        result = retrieval_service.semantic_search(repository_id, query=query, top_k=top_k)
    except httpx.HTTPError as exc:
        # 3. 记录失败日志及 repository_id
        # 不向客户端返回完整上游响应。
        logger.exception(repository_id)
        raise HTTPException(status_code=503, detail="Embedding service unavailable")

    # 4. result 为 None，返回 HTTP 404。
    if result is None:
        raise HTTPException(status_code=404, detail="Repository not found")

    # 5. 返回结果，包括合法的空列表。
    return result
